<script setup lang="ts">const props = defineProps<{ items: any[]; resource: string }>(); const emit = defineEmits<{ saved: [] }>(); const items = ref([...props.items]); function move(index: number, delta: number) { const target = index + delta; if (target < 0 || target >= items.value.length) return; [items.value[index], items.value[target]] = [items.value[target], items.value[index]] } async function save() { await $fetch(`/api/admin/${props.resource}/reorder`, { method: 'POST', body: { ids: items.value.map(item => item.id) } }); emit('saved') }</script>
<template><div class="space-y-2"><div v-for="(item, index) in items" :key="item.id" class="flex items-center justify-between rounded-xl border border-stone-200 bg-white px-4 py-3"><span>{{ item.title || item.label || item.value }}</span><span class="flex gap-2"><button type="button" :disabled="index === 0" @click="move(index, -1)">↑</button><button type="button" :disabled="index === items.length - 1" @click="move(index, 1)">↓</button></span></div><button type="button" class="rounded-full bg-emerald-900 px-4 py-2 text-sm text-white" @click="save">Save order</button></div></template>